from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[2];A=Path(__file__).parent
S=R/'output/launch-speed-JAPP138/source';C=R/'output/silk-launch-release'
changed=[]
for p in (S/'app').rglob('*'):
    if p.is_file() and (C/p.relative_to(S)).is_file() and p.read_bytes()!=(C/p.relative_to(S)).read_bytes():changed.append(p.relative_to(S).as_posix())
assert sorted(changed)==['app/css/launch.css','app/index.html','app/js/launch.js'],changed
tests=json.loads((S/'output/app-startup-results.json').read_text(encoding='utf-8'))
assert len(tests)==18 and all(t['passed'] for t in tests)
browser=json.loads((A/'browser-results.json').read_text(encoding='utf-8'));assert len(browser)==20
files=changed+['media/app/launch/flower-fast-standard.mp4','media/app/launch/flower-fast-tall.mp4']
(A/'manifest.json').write_text(json.dumps({p:hashlib.sha256((S/p).read_bytes()).hexdigest() for p in files},indent=2),encoding='utf-8')
(A/'startup-results.json').write_text(json.dumps(tests,ensure_ascii=False,indent=2),encoding='utf-8')
def add(path,text):
    p=R/path;old=p.read_text(encoding='utf-8');heading,rest=old.split('\n',1)
    assert '**J-APP-138 / T-APP-037' not in old
    p.write_text(heading+'\n\n'+text+'\n'+rest,encoding='utf-8',newline='\n')
add('project.md','**J-APP-138 / T-APP-037 — ускорение загрузки заставки и заполнение экрана, локально.** После замечания Альмиры с iPhone подготовлены ранняя загрузка выбранного MP4, облегчённые ролики и cover без зелёных полей сверху/снизу. Темп раскрытия 6/2,5 с сохранён. Проверки:9 автономных групп,20 браузерных запусков,18 startup-сценариев и структура60файлов. Изолированный просмотр, рабочая версия не менялась; скорость на iPhone после исправления ещё не проверена. [Результат](audit/launch-speed-JAPP138/REPORT.md). J-APP-137: получен отзыв о заставке; сохранение/возврат/черновики пока не подтверждены.')
add('База знаний/План.md','**J-APP-138 / T-APP-037 — подготовлено локальное исправление заставки.** Прямое поручение Альмиры: уменьшить ожидание закрытого бутона и заполнить площадь видео; уточнение — зелёные поля сверху и снизу, телефон iPhone. Результат — три узких изменения исходников и два облегчённых MP4 в отдельной копии; проверки завершены. Следующий шаг — просмотр Альмирой и отдельный выпуск, затем повтор на её iPhone. Публикация не выполнялась. [Проверки и границы](../audit/launch-speed-JAPP138/REPORT.md). T-APP-036 продолжается: отзыв о запуске получен, путь сохранения/возврата не подтверждён.')
add('База знаний/Журнал обсуждений.md','**J-APP-138 / T-APP-037 — обратная связь с iPhone при J-APP-137.** 19 октября2026 Альмира сообщила о долгом неподвижном закрытом бутоне и пожелала видео на всю площадь. Затем уточнила: «сверху и снизу зеленые поля»; на вопрос об устройстве ответила «iPhone». Точные секунды, версия Telegram и сеть неизвестны. В коде подтверждены contain и назначение src только после auth/access. Локально подготовлены cover и предварительная загрузка выбранного облегчённого MP4 одновременно со входом; воспроизведение/допуск остаются после прежней проверки. Ранее согласованный темп6/2,5с сохранён. Физическая причина задержки конкретной сети не установлена; результат браузера не подтверждает исправление телефона. [Результат и локальный просмотр](../audit/launch-speed-JAPP138/REPORT.md).')
add('База знаний/08 Решения.md','**J-APP-138 / T-APP-037 — согласовано заполнение заставки всей площадью и сокращение ожидания загрузки.** Источник — прямое замечание Альмиры19октября2026, уточнение о полях сверху/снизу и iPhone. Это пересматривает прежнее допущение небольшого фонового поля в J-SILK-017; при несовпадении пропорций края изображения могут обрезаться. Локальный кандидат готов и проверен; выпуск не выполнен. Темп движения не менялся, авторизация/данные/черновики/SDK/backend прежние. [Реализация и границы](../audit/launch-speed-JAPP138/REPORT.md).')
add('База знаний/07 Приложение и экосистема.md','**J-APP-138 / T-APP-037 — локальная правка загрузки заставки по отзыву с iPhone.** Выбранный облегчённый MP4 подгружается с DOMContentLoaded одновременно с серверным входом; play по-прежнему только после ready/authed/owner. Ранний отказ preload не запускает fallback/таймер до допуска; отмена освобождает src. Постер, video и animated fallback заполняют viewport через cover. Новые MP4561592/606111байт против1528381/1862236; движение6/2,5с, запасной WebP и таймеры прежние. В рабочем приложении пока прежняя версия. [Проверки, компромисс обрезки и просмотр](../audit/launch-speed-JAPP138/REPORT.md). J-APP-137: отзыв о заставке получен, остальные шаги ожидаются.')
p=R/'База знаний/Идеи и развитие.md';text=p.read_text(encoding='utf-8')
text=text.replace('короткий маршрут подготовлен, ожидается её телефонный результат. Условие продолжения — обратная связь по первому проходу; код/публикация не поручены.','короткий маршрут подготовлен; получен отзыв с iPhone о долгом закрытом бутоне и полях сверху/снизу. Адресная локальная правка J-APP-138/T-APP-037 подготовлена; путь сохранения и возврата ещё не подтверждён. Условие продолжения — просмотр исправления и повтор на телефоне, затем остальные шаги J-APP-137.')
p.write_text(text,encoding='utf-8',newline='\n')
p=R/'audit/phone-acceptance-JAPP137/CHECKLIST.md';text=p.read_text(encoding='utf-8')
text=text.replace('Подготовка выполнена; физические результаты пока не получены.','Подготовка выполнена; получен первый физический отзыв о заставке. Шаги сохранения и возврата пока не подтверждены.')
text=text.replace('| Устройство / версия Telegram / сеть | Нет данных |','| Устройство / версия Telegram / сеть | iPhone, со слов Альмиры; версия и сеть неизвестны |\n| Заставка | Долго стоит закрытый бутон; зелёные поля сверху и снизу. Точные секунды неизвестны. Локальный кандидат J-APP-138; повтор на телефоне ожидается |')
text=text.replace('Новых дефектов не подтверждено. Изменения кода, публикация и действия с рабочими данными ассистентом не выполнялись.','Получено замечание о заставке с телефона, [кандидат J-APP-138](../launch-speed-JAPP138/REPORT.md) подготовлен отдельно. Публикация и действия с рабочими данными не выполнялись. Успех записи/возврата этим отзывом не подтверждён.')
p.write_text(text,encoding='utf-8',newline='\n')
print('Recorded J-APP-138 local candidate and J-APP-137 phone feedback; no release.')
